import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ProprietaireService } from '../../core/services/proprietaire.service';

@Component({
  selector: 'app-proprietaire-form',
  templateUrl: './proprietaire-form.component.html'
})
export class ProprietaireFormComponent implements OnInit {
  form: FormGroup;
  loading = false;
  isEdit = false;
  id?: number;
  error = '';

  constructor(
    private fb: FormBuilder,
    private service: ProprietaireService,
    private route: ActivatedRoute,
    private router: Router
  ) {
    this.form = this.fb.group({
      nom: ['', Validators.required],
      telephone: ['', [Validators.required, Validators.pattern(/^[+]?[0-9\s\-]{8,20}$/)]],
      email: ['', [Validators.required, Validators.email]],
      adresse: [''],
      activite: [''],
      photo: ['']
    });
  }

  ngOnInit(): void {
    const idParam = this.route.snapshot.paramMap.get('id');
    if (idParam && idParam !== 'nouveau') {
      this.isEdit = true;
      this.id = +idParam;
      this.service.getById(this.id).subscribe({
        next: (p) => this.form.patchValue(p),
        error: () => this.router.navigate(['/proprietaires'])
      });
    }
  }

  onSubmit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    const obs = this.isEdit
      ? this.service.update(this.id!, this.form.value)
      : this.service.create(this.form.value);

    obs.subscribe({
      next: () => this.router.navigate(['/proprietaires']),
      error: (err) => {
        this.loading = false;
        this.error = err.error?.message || 'Erreur lors de l\'enregistrement';
      }
    });
  }
}
<div class="mb-4">
  <h1 class="page-title">{{ isEdit ? 'Modifier' : 'Ajouter' }} un propriétaire</h1>
  <p class="page-subtitle">
    <a routerLink="/proprietaires" class="text-muted">&larr; Retour à la liste</a>
  </p>
</div>

<div class="card" style="max-width:640px;">
  <div class="card-body">
    <div *ngIf="error" class="alert alert-danger">{{ error }}</div>
    <form [formGroup]="form" (ngSubmit)="onSubmit()">
      <div class="mb-3">
        <label class="form-label">Nom *</label>
        <input type="text" class="form-control" formControlName="nom">
      </div>
      <div class="row">
        <div class="col-md-6 mb-3">
          <label class="form-label">Téléphone *</label>
          <input type="text" class="form-control" formControlName="telephone" placeholder="+216 XX XXX XXX">
        </div>
        <div class="col-md-6 mb-3">
          <label class="form-label">Email *</label>
          <input type="email" class="form-control" formControlName="email">
        </div>
      </div>
      <div class="mb-3">
        <label class="form-label">Adresse</label>
        <input type="text" class="form-control" formControlName="adresse">
      </div>
      <div class="mb-3">
        <label class="form-label">Activité / Profession</label>
        <input type="text" class="form-control" formControlName="activite">
      </div>
      <div class="mb-3">
        <label class="form-label">Photo (URL)</label>
        <input type="text" class="form-control" formControlName="photo" placeholder="https://...">
      </div>
      <div class="d-flex gap-2">
        <button type="submit" class="btn btn-primary" [disabled]="loading || form.invalid">
          <span *ngIf="loading" class="spinner-border spinner-border-sm me-1"></span>
          {{ isEdit ? 'Mettre à jour' : 'Créer' }}
        </button>
        <a routerLink="/proprietaires" class="btn btn-outline-secondary">Annuler</a>
      </div>
    </form>
  </div>
</div>
